    //Driver Code Starts
using System;
using System.Collections.Generic;

class MinHeap
{
    private List<int[]> heap;

    public MinHeap()
    {
        heap = new List<int[]>();
    }

    public int Count => heap.Count;

    // Enqueue (node, distance)
    public void Enqueue(int node, int distance)
    {
        heap.Add(new int[] { distance, node });
        SiftUp(heap.Count - 1);
    }

    // Dequeue the smallest distance pair
    public bool TryDequeue(out int node, out int distance)
    {
        if (heap.Count == 0)
        {
            node = -1;
            distance = int.MaxValue;
            return false;
        }

        int[] top = heap[0];
        distance = top[0];
        node = top[1];

        int last = heap.Count - 1;
        heap[0] = heap[last];
        heap.RemoveAt(last);
        if (heap.Count > 0) SiftDown(0);
        return true;
    }

    private void SiftUp(int i)
    {
        while (i > 0)
        {
            int parent = (i - 1) / 2;
            if (heap[parent][0] <= heap[i][0]) break;
            Swap(i, parent);
            i = parent;
        }
    }

    private void SiftDown(int i)
    {
        int n = heap.Count;
        while (true)
        {
            int left = 2 * i + 1;
            int right = 2 * i + 2;
            int smallest = i;

            if (left < n && heap[left][0] < heap[smallest][0]) smallest = left;
            if (right < n && heap[right][0] < heap[smallest][0]) smallest = right;

            if (smallest == i) break;
            Swap(i, smallest);
            i = smallest;
        }
    }

    private void Swap(int i, int j)
    {
        int[] temp = heap[i];
        heap[i] = heap[j];
        heap[j] = temp;
    }
}

class GFG
{
//Driver Code Ends

    static List<int> dijkstra(List<List<int[]>> adj, int src)
    {
        int V = adj.Count;

        // Min-heap (priority queue) storing pairs of (distance, node)
        MinHeap pq = new MinHeap();

        // Distance array: stores shortest distance from source
        int[] dist = new int[V];
        for (int i = 0; i < V; i++)
            dist[i] = int.MaxValue;

        // Distance from source to itself is 0
        dist[src] = 0;
        pq.Enqueue(src, 0);

        // Process the queue until all reachable vertices are finalized
        while (pq.Count > 0)
        {
            pq.TryDequeue(out int u, out int d);

            // If this distance is not the latest shortest one, skip it
            if (d > dist[u])
                continue;

            // Explore all adjacent vertices
            foreach (var p in adj[u])
            {
                int v = p[0];
                int w = p[1];

                // If we found a shorter path to v through u, update it
                if (dist[u] + w < dist[v])
                {
                    dist[v] = dist[u] + w;
                    pq.Enqueue(v, dist[v]);
                }
            }
        }

        // Convert result to List for output
        List<int> result = new List<int>();
        foreach (int d in dist)
            result.Add(d);

        // Return the final shortest distances from the source
        return result;
    }


//Driver Code Starts
    static void addEdge(List<List<int[]>> adj, int u, int v, int w)
    {
        adj[u].Add(new int[] { v, w });
        adj[v].Add(new int[] { u, w });
    }

    static void Main()
    {
        int V = 5;
        int src = 0;

        List<List<int[]>> adj = new List<List<int[]>>();
        for (int i = 0; i < V; i++)
            adj.Add(new List<int[]>());

        addEdge(adj, 0, 1, 4);
        addEdge(adj, 0, 2, 8);
        addEdge(adj, 1, 2, 3);
        addEdge(adj, 1, 4, 6);
        addEdge(adj, 2, 3, 2);
        addEdge(adj, 3, 4, 10);

        List<int> result = dijkstra(adj, src);
        foreach (int d in result)
            Console.Write(d + " ");
        Console.WriteLine();
    }
}

